import { NextRequest, NextResponse } from 'next/server';
import {
  getServerApiCandidates,
  isRetryableApiResponseStatus,
} from '@/lib/api-config';
import {
  DASHBOARD_DEBUG_ROLE_COOKIE_NAME,
  DASHBOARD_DEBUG_ROLE_HEADER_NAME,
  parseDashboardDebugRoleCookie,
} from '@/lib/dashboard-auth';

const FORWARDED_FOR_FALLBACK_HEADER_NAMES = [
  'x-real-ip',
  'cf-connecting-ip',
  'true-client-ip',
  'x-client-ip',
  'x-vercel-forwarded-for',
] as const;

function appendDistinctForwardedForValues(values: string[], raw: string | null) {
  if (!raw) {
    return;
  }

  for (const part of raw.split(',')) {
    const candidate = part.trim();
    if (candidate && !values.includes(candidate)) {
      values.push(candidate);
    }
  }
}

function getForwardedForHeader(request: NextRequest) {
  const values: string[] = [];

  appendDistinctForwardedForValues(values, request.headers.get('x-forwarded-for'));

  for (const headerName of FORWARDED_FOR_FALLBACK_HEADER_NAMES) {
    appendDistinctForwardedForValues(values, request.headers.get(headerName));
  }

  return values.join(', ') || null;
}

function getForwardedProtoHeader(request: NextRequest) {
  return (
    request.headers.get('x-forwarded-proto') ??
    request.nextUrl.protocol.replace(/:$/, '')
  );
}

function getForwardedHostHeader(request: NextRequest) {
  return (
    request.headers.get('x-forwarded-host') ??
    request.headers.get('host') ??
    request.nextUrl.host
  );
}

function buildForwardHeaders(request: NextRequest) {
  const headers = new Headers();
  const debugRole = parseDashboardDebugRoleCookie(
    request.cookies.get(DASHBOARD_DEBUG_ROLE_COOKIE_NAME)?.value,
  );

  for (const name of [
    'accept',
    'accept-language',
    'authorization',
    'content-type',
    'idempotency-key',
    'user-agent',
    'x-event-checksum',
    'x-idempotency-key',
    'x-request-id',
    'x-correlation-id',
  ]) {
    const value = request.headers.get(name);
    if (value) {
      headers.set(name, value);
    }
  }

  if (debugRole) {
    headers.set(DASHBOARD_DEBUG_ROLE_HEADER_NAME, debugRole);
  }

  const forwardedFor = getForwardedForHeader(request);
  if (forwardedFor) {
    headers.set('x-forwarded-for', forwardedFor);
  }

  const forwardedProto = getForwardedProtoHeader(request);
  if (forwardedProto) {
    headers.set('x-forwarded-proto', forwardedProto);
  }

  const forwardedHost = getForwardedHostHeader(request);
  if (forwardedHost) {
    headers.set('x-forwarded-host', forwardedHost);
  }

  return headers;
}

async function forwardRequest(
  request: NextRequest,
  context: { params: Promise<{ path: string[] }> },
) {
  const { path } = await context.params;
  const pathname = path.join('/');
  const query = request.nextUrl.search;
  const headers = buildForwardHeaders(request);
  const body =
    request.method === 'GET' || request.method === 'HEAD'
      ? undefined
      : await request.arrayBuffer();

  let lastError: unknown;
  const attemptedUrls: string[] = [];

  for (const baseUrl of getServerApiCandidates()) {
    const targetUrl = `${baseUrl}/${pathname}${query}`;
    attemptedUrls.push(targetUrl);

    try {
      if (pathname.startsWith('shipping/')) {
        console.log(
          `[api/proxy] ${request.method} ${pathname} -> ${targetUrl} auth=${headers.has('authorization')}`,
        );
      }
      const upstreamResponse = await fetch(targetUrl, {
        method: request.method,
        headers,
        body,
        cache: 'no-store',
        signal: AbortSignal.timeout(10_000),
      });

      if (isRetryableApiResponseStatus(upstreamResponse.status)) {
        await upstreamResponse.body?.cancel().catch(() => undefined);
        lastError = new Error(
          `API candidate ${targetUrl} returned transient status ${upstreamResponse.status}`,
        );
        continue;
      }

      if (pathname.startsWith('shipping/')) {
        console.log(
          `[api/proxy] ${request.method} ${pathname} <- ${upstreamResponse.status} from ${targetUrl}`,
        );
      }

      const responseHeaders = new Headers(upstreamResponse.headers);
      responseHeaders.delete('content-encoding');
      responseHeaders.delete('transfer-encoding');

      return new NextResponse(upstreamResponse.body, {
        status: upstreamResponse.status,
        statusText: upstreamResponse.statusText,
        headers: responseHeaders,
      });
    } catch (error) {
      lastError = error;
    }
  }

  const detail =
    lastError instanceof Error ? lastError.message : 'Sin detalle adicional';

  return NextResponse.json(
    {
      message: `No fue posible conectar con la API. URLs probadas: ${attemptedUrls.join(', ')}. Detalle: ${detail}`,
    },
    { status: 502 },
  );
}

export async function GET(
  request: NextRequest,
  context: { params: Promise<{ path: string[] }> },
) {
  return forwardRequest(request, context);
}

export async function POST(
  request: NextRequest,
  context: { params: Promise<{ path: string[] }> },
) {
  return forwardRequest(request, context);
}

export async function PUT(
  request: NextRequest,
  context: { params: Promise<{ path: string[] }> },
) {
  return forwardRequest(request, context);
}

export async function PATCH(
  request: NextRequest,
  context: { params: Promise<{ path: string[] }> },
) {
  return forwardRequest(request, context);
}

export async function DELETE(
  request: NextRequest,
  context: { params: Promise<{ path: string[] }> },
) {
  return forwardRequest(request, context);
}

export async function HEAD(
  request: NextRequest,
  context: { params: Promise<{ path: string[] }> },
) {
  return forwardRequest(request, context);
}
